#!/usr/bin/env bash
# Generated by Agent Team Kit 0.7.1. Do not edit: fixes go upstream, settings go in .agent-team/config.sh.
# Regenerates this repository's agent team from .agent-team/, using the Agent Team Kit version pinned in
# .agent-team/team.json ("kit"). To upgrade the kit, change that pin and run this script.
#
#   scripts/agent-team/sync.sh          regenerate docs/team/, scripts/agent-team/ (and .claude/agents/)
#   scripts/agent-team/sync.sh check    exit 1 when a generated file is out of date or was edited by hand (for CI)
#   scripts/agent-team/sync.sh roles    list the roles and where each comes from
#
# AGENT_TEAM_KIT_DIR=/path/to/a/kit/checkout uses a local copy of the kit instead of npx (for kit development).
set -euo pipefail
root="$(git rev-parse --show-toplevel 2>/dev/null || pwd)"
cd "$root"
cmd="${1:-sync}"; [ $# -gt 0 ] && shift
if [ -n "${AGENT_TEAM_KIT_DIR:-}" ]; then
  exec node "$AGENT_TEAM_KIT_DIR/bin/agent-team.mjs" "$cmd" "$@"
fi
kit="$(node -e 'process.stdout.write(JSON.parse(require("fs").readFileSync(".agent-team/team.json","utf8")).kit)')"
exec npx --yes "$kit" "$cmd" "$@"
